import {b,fmt,clamp,shells,heating,work,buoyancy,pendulum,falling} from '../math.js';
import {C,reflect,read,particles,molecule,atom,cell,neuron,plants,organelles} from '../scene-utils.js';
export default ({g,p,extra})=>{let q=p[0]/100,method=Number(extra.method??0);g.box(-.65,0,0,.45,.7,.5);g.box(.65,0,0,.45,.7,.5);for(let i=0;i<24;i++){let x=-.65+Math.sin(i*5)*.32,y=Math.cos(i*7)*.5,z=Math.sin(i*3)*.35,isSolid=i<8;if(method===0){if(!isSolid)x+=1.3*q;else y=y*(1-q)+.5*q;}if(method===1){if(!isSolid)y-=q*1.6;else y=y*(1-q)+.5*q;}if(method===2){if(isSolid)x+=1.3*q;else y=y*(1-q)+.4*q;}if(method===3){if(!isSolid)x+=1.3*q;}g.sphere(x,y,z,isSolid?.08:.035,isSolid?C.gold:C.blue)}g.arrow([-.1,-.9,0],[.5,-.9,0],C.green);return[read('Process progress','प्रक्रिया प्रगति',p[0],'%'),{label:b('Method','विधि'),value:[b('Filtration: insoluble solid stays','छानना: अघुलनशील ठोस रुकता है'),b('Evaporation: solvent leaves','वाष्पीकरण: विलायक निकलता है'),b('Magnet: magnetic solid moves','चुम्बक: चुम्बकीय ठोस अलग होता है'),b('Distillation: solvent collected','आसवन: विलायक एकत्र होता है')][method]}];};
